import java.util.*;
import java.io.*;

public class Main {
    static int[] simulate(int n, int m, int k, int[][] moves) {
        // Write your solution here
        return new int[moves.length];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int k = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        int[][] moves = new int[q][3];
        for (int i = 0; i < q; i++) {
            for (int j = 0; j < 3; j++) {
                in.nextToken();
                moves[i][j] = (int) in.nval;
            }
        }
        int[] res = simulate(n, m, k, moves);
        StringBuilder sb = new StringBuilder();
        for (int x : res) sb.append(x).append('\n');
        System.out.print(sb);
    }
}
